SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF NOT EXISTS(SELECT 1 FROM dbo.Departments WHERE DepartmentName=N'Demo Department') INSERT dbo.Departments(DepartmentName) VALUES(N'Demo Department');
DECLARE @DepartmentId INT=(SELECT DepartmentId FROM dbo.Departments WHERE DepartmentName=N'Demo Department');
IF NOT EXISTS(SELECT 1 FROM dbo.Users WHERE Email=N'customer@example.test') INSERT dbo.Users(SchoolId,FullName,Email,DepartmentId,RoleId,CustomerType) SELECT N'DEMO-CUSTOMER',N'Demo Customer',N'customer@example.test',@DepartmentId,RoleId,N'Demo' FROM dbo.Roles WHERE RoleName=N'Customer';
IF NOT EXISTS(SELECT 1 FROM dbo.Users WHERE Email=N'staff@example.test') INSERT dbo.Users(SchoolId,FullName,Email,DepartmentId,RoleId) SELECT N'DEMO-STAFF',N'Demo Staff',N'staff@example.test',@DepartmentId,RoleId FROM dbo.Roles WHERE RoleName=N'Staff';
IF NOT EXISTS(SELECT 1 FROM dbo.Users WHERE Email=N'admin@example.test') INSERT dbo.Users(SchoolId,FullName,Email,DepartmentId,RoleId) SELECT N'DEMO-ADMIN',N'Demo Admin',N'admin@example.test',@DepartmentId,RoleId FROM dbo.Roles WHERE RoleName=N'Admin';
IF NOT EXISTS(SELECT 1 FROM dbo.Categories WHERE CategoryName=N'Demo Apparel') INSERT dbo.Categories(CategoryName) VALUES(N'Demo Apparel');
IF NOT EXISTS(SELECT 1 FROM dbo.Categories WHERE CategoryName=N'Demo Accessories') INSERT dbo.Categories(CategoryName) VALUES(N'Demo Accessories');
DECLARE @CategoryId INT=(SELECT CategoryId FROM dbo.Categories WHERE CategoryName=N'Demo Apparel');
IF NOT EXISTS(SELECT 1 FROM dbo.Products WHERE SKU=N'DEMO-SHIRT') INSERT dbo.Products(CategoryId,SKU,ProductName,Description,Price,IsFeatured) VALUES(@CategoryId,N'DEMO-SHIRT',N'Demo Bulldogs Shirt',N'Development data only',350,1);
DECLARE @ProductId INT=(SELECT ProductId FROM dbo.Products WHERE SKU=N'DEMO-SHIRT');
IF NOT EXISTS(SELECT 1 FROM dbo.ProductVariants WHERE VariantSKU=N'DEMO-SHIRT-M') INSERT dbo.ProductVariants(ProductId,VariantName,VariantSKU) VALUES(@ProductId,N'Medium',N'DEMO-SHIRT-M');
DECLARE @VariantId INT=(SELECT ProductVariantId FROM dbo.ProductVariants WHERE VariantSKU=N'DEMO-SHIRT-M');
IF NOT EXISTS(SELECT 1 FROM dbo.Inventory WHERE ProductVariantId=@VariantId) INSERT dbo.Inventory(ProductVariantId,PhysicalQuantity,ReservedQuantity,ReorderLevel) VALUES(@VariantId,20,2,5);
DECLARE @CustomerId INT=(SELECT UserId FROM dbo.Users WHERE Email=N'customer@example.test');
IF NOT EXISTS(SELECT 1 FROM dbo.Reservations WHERE Reference=N'BX-DEMO-0001') INSERT dbo.Reservations(Reference,CustomerId,ReservationStatusId,ExpiresAt) SELECT N'BX-DEMO-0001',@CustomerId,ReservationStatusId,DATEADD(day,7,SYSUTCDATETIME()) FROM dbo.ReservationStatuses WHERE StatusName=N'Confirmed';
DECLARE @ReservationId INT=(SELECT ReservationId FROM dbo.Reservations WHERE Reference=N'BX-DEMO-0001');
IF NOT EXISTS(SELECT 1 FROM dbo.ReservationItems WHERE ReservationId=@ReservationId AND ProductVariantId=@VariantId) INSERT dbo.ReservationItems(ReservationId,ProductVariantId,Quantity,UnitPrice) VALUES(@ReservationId,@VariantId,2,350);
IF NOT EXISTS(SELECT 1 FROM dbo.QueueEntries WHERE ReservationId=@ReservationId AND CompletedAt IS NULL) INSERT dbo.QueueEntries(QueueNumber,CustomerId,ReservationId,QueueTypeId,QueueStatusId) SELECT N'R-DEMO-001',@CustomerId,@ReservationId,qt.QueueTypeId,qs.QueueStatusId FROM dbo.QueueTypes qt CROSS JOIN dbo.QueueStatuses qs WHERE qt.QueueTypeName=N'Regular' AND qs.StatusName=N'Waiting';
COMMIT;
